import {countryTargetButtons} from './country-inquiry.js?v=174';
import {recruitCard,selectedRecruitSlots,recruitControls,visibleRecruits} from './recruit-selection.js?v=174';
import {aiDifficultyControl} from './ai-difficulty.js?v=174';
import {threatPanel} from './threats-ui.js?v=174';
import {personnelPanel} from './personnel-ui.js?v=174';
import {quickActionMarkup} from './quick-actions.js?v=174';
import {teamBalanceMarkup} from './team-balance.js?v=174';
import {COOPERATION,cooperationRules} from './cooperation.js?v=174';
import {technologyPanel} from './technology-ui.js?v=174';
import {prestigeHistory} from './prestige.js?v=174';
import {countrySignals} from './country-signals.js?v=174';
import {suspectPortrait,SUSPECT_PROFILES,identityKnown} from './fracture-profiles.js?v=174';
import {plotStage} from './fracture.js?v=174';
import {activityRows,techUnavailable} from './experience.js?v=174';
import {exposureBar,evidenceSummary,evidenceRegister,nationalPanel,foreignProgress} from './command-ui.js?v=174';
import {reportCards,internationalActivity} from './operations-ui.js?v=174';
import {proofTitle} from './intelligence.js?v=174';
import {countryOptions,statusBadge,availability,progressMarkup,sortedCaseTargets} from './presentation.js?v=174';
import {renderMap} from './map.js?v=174';
import {cityArt,fullBody} from './visuals.js?v=174';
import {COUNTRIES,COUNTRY,DISPLAY_ROSTER as ROSTER,TALENTS,STAT_NAMES,ACTIONS,CELLS,EVIDENCE_NAMES,TECH} from './data.js?v=174';
import * as E from './engine.js?v=174';
import {esc,icon,button,flag,nationalities,nationalityFlags,talentIcon,portrait,statlines,talents,fatigue,brand,heading,formatScore} from './ui.js?v=174';
export function setupScreen(country,agents,hasSave,mp=null,aiDifficulty='normal'){return `<div class="setup-shell"><header>${brand()}<div class="classified">ACCÈS RESTREINT <span>● CONNEXION SÉCURISÉE</span></div></header><main class="setup-main">${mp?.header||''}${heading('','Opération Ligne de faille','')}<div class="setup-columns"><div class="setup-selection"><section class="setup-country"><div class="section-title"><h2><span>01</span> Choisir votre pays</h2></div><div class="country-grid">${COUNTRIES.filter(c=>c.power).map(c=>`<button class="nation ${c.id===country?'selected':''}" data-cmd="${mp?'mp-country':'country'}" data-id="${c.id}" ${mp?.taken?.includes(c.id)?'disabled':''} aria-pressed="${c.id===country}">${flag(c.id)}<div><strong>${c.name}</strong></div>${c.id===country?icon('check'):''}</button>`).join('')}</div></section><div class="section-title"><h2><span>02</span> Composer votre unité</h2><span class="count">${agents.length} / 4 agents sélectionnés</span></div>${selectedRecruitSlots(agents,mp?'multi':'solo')}${recruitControls(mp?'multi':'solo')}<div class="recruit-grid">${visibleRecruits(mp?'multi':'solo').map(a=>recruitCard(a,agents,mp?'multi':'solo')).join('')}</div></div><aside class="briefing panel">${teamBalanceMarkup(agents)}${mp?'':aiDifficultyControl(aiDifficulty)}${mp?'':button('Lancer l’opération','start','primary setup-launch',agents.length!==4?'disabled':'')}</aside></div></main><footer>PROGRAMME SIGMA / DIVISION RENSEIGNEMENT <span>2040 · LIGNE DE FAILLE</span></footer></div>`;}
export function makeScreens(state,selectedCountry,selectedAgent,world,camera){
const f=state.factions[state.player];
function agentStatus(a){return a.status==='captured'?'En détention':a.status==='injured'?'Blessé':a.task?`${a.task.queued?'Ordre planifié':'En opération'} · ${a.task.remaining} t`:'Disponible';}
function teamCards(){const pending=state.recruitments.filter(r=>r.faction===state.player);return `<div class="team-grid">${E.team(state).map(a=>{const b=availability(a),t=a.task;return `<button class="agent-card state-${b.kind} ${t?'busy':''}" data-cmd="map-agent" data-id="${a.id}" aria-pressed="${selectedAgent===a.id}" title="Double-cliquez pour affecter · ${esc(a.name)} · ${COUNTRY[a.country].city} · ${t?ACTIONS[t.type].name+' · '+t.remaining+' tour(s)':b.label} · ${100-a.fatigue}/100 énergie">${portrait(a)}<div class="agent-card-copy"><h3>${esc(a.name)} ${nationalityFlags(a)}</h3><span class="availability ${b.kind}">${icon(b.icon)}${t?.queued?'PLANIFIÉ':b.label}${t?` <small>· ${t.remaining} t</small>`:''}</span><div class="agent-brief"><span>${COUNTRY[a.country].city}${t&&['travel','sneak'].includes(t.type)?' → '+COUNTRY[t.target].city:''}</span><span class="compact-energy" title="Énergie et exposition">É ${100-a.fatigue} · Exp ${a.exposure}</span></div>${t?`<progress class="compact-progress" aria-label="Progression de ${esc(ACTIONS[t.type].name)}" max="${t.total}" value="${t.total-t.remaining}"></progress>`:''}</div></button>`;}).join('')}${pending.map(r=>`<div class="empty-slot pending-recruit" role="status">${icon('clock')}<span><strong>${esc(ROSTER.find(a=>a.id===r.id)?.name||r.id)}</strong><small>Arrivée dans ${r.remaining} tour(s)</small></span></div>`).join('')}${Array.from({length:Math.max(0,4-E.team(state).length-pending.length)},()=>`<button class="empty-slot" data-cmd="recruit">${icon('plus')} Recruter</button>`).join('')}</div>`;}
function worldScreen(){const c=COUNTRY[selectedCountry],plots=E.visiblePlots(state),local=E.knownTargets(state).filter(t=>t.country===c.id&&!t.arrested),here=E.team(state).filter(a=>a.country===c.id),foreign=Object.values(f.publicAgents).filter(a=>a.country===c.id&&(a.source!=='counter'||a.until>=state.turn)),logs=E.visibleLogs(state).slice(0,3),active=E.team(state).find(a=>a.id===selectedAgent);return `<h1 class="sr-only">Situation mondiale</h1><div class="world-overview"><section class="world-center">${renderMap(state,selectedCountry,world,camera)}<div class="objective-strip">${icon('cuffs')}<span><strong>${state.suspects.filter(t=>t.arrested).length} / 7</strong> arrestations</span><span><strong>${E.cellsDone(state).length} / 2</strong> cellules</span><span class="mission-objective">Capturer L’Architecte · Empêcher les attaques</span></div></section><details class="map-dossier" ${camera.panelOpen?'open':''}><summary>${icon(active?'people':'world')} ${active?esc(active.name):c.name}<span> Dossier</span></summary>${active?`<aside class="country-dossier agent-focus panel"><div class="focus-heading">${portrait(active)}<div><span class="eyebrow">AGENT SÉLECTIONNÉ</span><h2>${active.name} ${nationalityFlags(active)}</h2><p>${active.role}</p></div></div>${statusBadge(active)}<p>${COUNTRY[active.country].city}</p>${activeMission(state,active)}${fatigue(active)}${exposureBar(active)}${button(icon('target')+' Affecter une opération','agent',active.task?'wide assignment-unavailable':'primary wide','data-id="'+active.id+'"'+(active.task?' disabled title="Annulez la mission actuelle pour affecter un nouvel ordre."':''))}${quickActionMarkup(state,active)}<h3>Capacités</h3><div class="focus-stats">${active.stats.map((n,i)=>`<div class="focus-stat" title="${STAT_NAMES[i]} : ${n} sur 10"><span>${icon(['scan','target','shield'][i])}${n}</span><small>${STAT_NAMES[i]}</small></div>`).join('')}</div><h3>Talents</h3>${talents(active)}<div class="focus-secondary">${button('Dossier complet','select-agent','wide','data-id="'+active.id+'"')}${button('Journal de l’agent','agent-journal','wide','data-id="'+active.id+'"')}${button('Voir le pays','map-country','wide','data-id="'+active.country+'"')}</div></aside>`:`<aside class="country-dossier panel"><div class="country-title">${flag(c.id)}<div><h2>${c.name}</h2><p>${c.power?'PUISSANCE ACTIVE':c.sector.toUpperCase()}</p></div></div><div class="country-title-signals">${countrySignals(state,c.id)}</div>${countryTargetButtons(state,c.id)}${cityArt(c.id,'dossier-city')}${button(`${icon('plane')} Déployer un agent ${icon('arrow')}`,'deploy','primary wide')}<div class="country-instruments"><div class="inset authority-instrument"><span>COOPÉRATION DES AUTORITÉS</span><strong class="instrument-word">${COOPERATION[f.cooperation[c.id]].name}</strong><small>Mandat ${COOPERATION[f.cooperation[c.id]].mandate>0?'+':''}${COOPERATION[f.cooperation[c.id]].mandate} · Localiser / arrestation avec mandat ${COOPERATION[f.cooperation[c.id]].field>0?'+':''}${COOPERATION[f.cooperation[c.id]].field} points${f.cooperation[c.id]===4?' · Surveillance +1 tour':''}</small></div><div class="inset" title="Exposition la plus élevée parmi vos agents présents. Dès 20 : repérable ; 40 : malus sensible ; 60 : malus enquête ; 80 : pression accrue. Ce n’est pas une vigilance du pays."><span>EXPOSITION DES AGENTS</span><strong>${here.length?Math.max(...here.map(a=>a.exposure))+' / 100':'—'}</strong><small>${here.length?'Maximum sur place · repérable dès 20':'Aucun de vos agents sur place'}</small></div><div class="inset"><span>PISTES</span><strong>${local.length}</strong><small>à explorer</small></div></div><div class="presence-summary"><span>${icon('people')} ${here.length} agent(s) de votre unité</span>${foreign.length?`<details><summary>${foreign.length} passage(s) étranger(s)</summary>${foreign.map(a=>`<p>${flag(a.faction)} ${esc(a.name)} · Équipe ${COUNTRY[a.faction].name} · ${COUNTRY[a.country].name} · Repéré T${a.turn}</p>`).join('')}</details>`:''}</div>${button(`${icon('target')} Centrer la carte`,'focus-map','wide')}</aside>`}</details></div><section class="field-team panel"><div class="panel-bar"><span>VOS AGENTS SUR LE TERRAIN</span><span>${E.team(state).filter(a=>!a.task&&a.status!=='captured').length} DISPONIBLE(S)</span></div>${teamCards()}</section>`;}
function agentsScreen(){return personnelPanel(state,selectedAgent);}
function suspectCard(t){const k={...E.dossier(state,state.player,t.id),locationUntil:E.locationExpiry(state,state.player,t.id)},e=E.evidenceFor(state,state.player,t.id),verified=e.filter(e=>e.verified).length;return `<button class="suspect-card panel ${t.arrested?'resolved':''} ${t.cell===3?'mastermind':''}" data-cmd="country-inquiry" data-id="${t.id}"><div class="suspect-top"><span class="eyebrow">${t.cell===3?'COMMANDEMENT':CELLS[t.cell]}</span><span class="tag ${t.arrested?'good':''}">${t.arrested?'ARRÊTÉ'+(t.arrestedBy?' · '+esc(COUNTRY[t.arrestedBy]?.name||t.arrestedBy):''):'DOSSIER'}</span></div><div class="suspect-identity">${suspectPortrait(t)}<div><h3>${t.name}</h3><p>${t.role}</p><small>${identityKnown(t)?SUSPECT_PROFILES[t.templateId??t.id].trait:'Portrait non disponible'}</small></div></div><div class="suspect-country">${flag(k.country)} ${COUNTRY[k.country].name}<span>${k.locationUntil>=state.turn?'Position confirmée':'Position à établir'}</span></div>${k.flightUntil&&!t.arrested?`<p class="decision-warning">Départ signalé · fin du tour ${k.flightUntil}</p>`:''}${progressMarkup(state,t)}<div class="suspect-meta"><span>${t.arrested?'Affaire terminée':`${e.length} preuve(s) recueillie(s) · ${verified} vérifiée(s)`}</span>${icon('chevron')}</div></button>`;}
function inquiryScreen(){const targets=sortedCaseTargets(state);return `<div class="inquiry-header">${heading('','Le réseau Fracture','Dossiers triés par progression',`<div class="objective-chip">${icon('file')} ${E.evidenceQueue(state,state.player).length} preuve(s) à vérifier au QG</div>`)}<div class="inquiry-status"><section class="lead-research panel"><div><strong>${icon('radar')} Recherche d’un nouveau dossier</strong><span>${state.suspects.some(t=>t.id!=='s6'&&!t.arrested&&!E.dossier(state,state.player,t.id))?E.leadResearch(state).progress+' / 3 points':'Tous les dossiers accessibles sont connus'}</span></div><progress max="3" value="${E.leadResearch(state).progress}" aria-label="Recherche d’un nouveau dossier"></progress><p>Contact / intrusion / IA +1 · Contre-espionnage +2 <span class="research-rule">Meilleur gain par tour · surplus conservé</span></p></section><div class="inquiry-objective panel"><div>${icon('radar')}<div><strong>Objectif collectif</strong><p>Arrêter L’Architecte et démanteler au moins deux cellules complètes.</p></div></div><div class="cell-status">${CELLS.map((c,i)=>`<span class="${E.cellsDone(state).includes(i)?'done':''}">${icon(E.cellsDone(state).includes(i)?'check':'target')} ${c.split(' ')[1]} ${state.suspects.filter(t=>t.cell===i&&t.arrested).length}/2</span>`).join('')}</div></div></div></div>${evidenceSummary(state)}<div class="suspect-grid">${targets.filter(t=>!t.arrested).map(suspectCard).join('')}${state.suspects.filter(t=>!t.arrested&&!E.dossier(state,state.player,t.id)).map(t=>`<div class="unknown-target panel">${icon('lock')}<strong>${t.cell===3?'Direction inconnue':'Dossier à découvrir'}</strong><p>${t.cell===3?'Démantelez deux cellules ou recoupez les preuves de trois suspects.':'Activez des contacts ou menez une opération de contre-espionnage.'}</p></div>`).join('')}${targets.filter(t=>t.arrested).map(suspectCard).join('')}${state.suspects.filter(t=>t.arrested&&!E.dossier(state,state.player,t.id)).map(t=>`<div class="unknown-target panel arrested"><strong>Cible arrêtée</strong><p>Dossier non détenu par votre équipe.${t.arrestedBy?' Arrestation : '+esc(COUNTRY[t.arrestedBy]?.name||t.arrestedBy):''}</p></div>`).join('')}</div><details class="panel evidence-panel"><summary class="evidence-summary">${icon('file')} Registre des preuves <span>${f.evidence.length} pièce(s) · ouvrir / fermer</span></summary>${evidenceRegister(state)}</details>`;}
function operationsScreen(){const tasks=E.team(state).filter(a=>a.task);return `${heading('04 / PLANIFICATION','Opérations & soutien','Les ordres se résolvent en fin de tour ; en multijoueur, leur ordre est tiré au sort à chaque tour.',`<span class="objective-chip">${icon('clock')} ${tasks.length} opération(s) en cours</span>`)}<div class="ops-layout technology-layout">${technologyPanel(state,selectedCountry)}<section class="panel operations-list console-orders"><div class="section-title"><h2>Ordres de l’unité</h2><span class="muted">Missions gratuites · renforts facultatifs</span></div>${tasks.length?tasks.map(a=>`<div class="operation-row">${portrait(a)}<div><span class="eyebrow">${a.name} / ${COUNTRY[a.country].city}</span><h3>${ACTIONS[a.task.type].name}</h3><p>${COUNTRY[a.task.target]?.name||state.suspects.find(t=>t.id===a.task.target)?.name||'Opération locale'} · ${a.task.queued?'En attente du prochain tour':'En cours'}</p><progress max="${a.task.total}" value="${a.task.total-a.task.remaining}"></progress></div><div class="operation-numbers"><strong>${a.task.remaining} <small>tour(s)</small></strong><span>${a.task.cost} crédits engagés</span>${(E.travelInProgress(a)?'<span class="muted">Déplacement en cours · non annulable</span>':button('Annuler','cancel','small','data-id="'+a.id+'"'))}</div></div>`).join(''):`<div class="empty-state">${icon('target')}<h3>Aucun ordre engagé</h3><p>Sélectionnez un agent pour préparer votre prochaine opération.</p>${button('Affecter un agent','deploy')}</div>`}<p class="console-order-help">Annuler libère l’agent et abandonne sa progression. Un déplacement commencé ne peut pas être annulé.</p><div class="console-team">${E.team(state).map(a=>button(`${portrait(a)}<span><b>${esc(a.name)}</b><small>${COUNTRY[a.country].city} · ${a.task?'Occupé':a.status==='captured'?'Capturé':'Disponible'}</small></span>`,'agent','','data-id="'+a.id+'"')).join('')}</div><details class="report-details"><summary>Derniers comptes rendus de mission</summary>${reportCards(state)}</details></section></div>`;}
function countryRelation(c,index){if(c.power){const own=c.id===state.player,faction=state.factions[c.id];return `<article class="panel power-compact"><header>${flag(c.id)}<div><h3>${esc(c.name)}</h3><small>${esc(c.city)}${own?' · Votre pays':''}</small></div><strong class="power-score">${formatScore(faction.score)}<small>prestige · #${index+1}</small></strong></header><div class="power-controls">${countrySignals(state,c.id)}${own?button('Gouvernement','nav','small','data-id="government"'):''}</div></article>`;}const own=c.id===state.player,ff=state.factions[c.id],agents=E.team(state).filter(a=>a.country===c.id),seen=Object.values(f.publicAgents).filter(a=>a.country===c.id&&(a.source!=='counter'||a.until>=state.turn)),protectedUntil=Math.max(0,...Object.values(state.factions).map(x=>x.defense[c.id]||0)),support=f.cyberSupport?.[c.id],coop=f.cooperation[c.id],protectedNow=protectedUntil>=state.turn;return `<article class="panel relation-card compact-relation ${own?'your-faction':''}"><div class="relation-banner">${cityArt(c.id,'relation-city')}<header>${flag(c.id)}<div><h3>${c.name}</h3><span>${c.city}${own?' · Votre pays':''}</span></div>${ff?`<span class="relation-rank" title="Classement par prestige">#${index+1}</span>`:''}</header></div><div class="relation-overview"><span>Coopération des autorités <strong>${COOPERATION[coop].name}</strong></span><span>Prestige <strong>${ff?formatScore(ff.score):'—'}${ff?'<small> pts</small>':''}</strong></span></div><div class="relation-signals">${countrySignals(state,c.id)}</div><details class="relation-details"><summary>Renseignements et actions${seen.length?` · ${seen.length} présence(s) signalée(s)`:''}</summary><div class="relation-detail-body"><dl><div><dt>Relation</dt><dd>${own?'Votre pays':COOPERATION[coop].name}</dd></div><div><dt>Appui des autorités</dt><dd>Mandat : ${COOPERATION[coop].mandate>0?'+':''}${COOPERATION[coop].mandate} points · Localisation et arrestation avec mandat : ${COOPERATION[coop].field>0?'+':''}${COOPERATION[coop].field} points${coop===4?' · Surveillance +1 tour':''}</dd></div><div><dt>Couverture de vos agents</dt><dd>${agents.length?agents.map(a=>esc(a.name)+' · '+esc(a.cover)).join('<br>'):'Aucun agent sur place'}</dd></div><div><dt>Planque de l’équipe</dt><dd>${(c.id===state.player||E.hasSafehouse(state,state.player,c.id))?'Disponible pour tous vos agents':'À trouver'}</dd></div><div><dt>Hack d’un pays</dt><dd>${support?.until>=state.turn?'+10 · jusqu’à T'+support.until:'Inactif'}</dd></div>${ff?`<div><dt>Arrestations</dt><dd>${state.suspects.filter(t=>t.arrestedBy===c.id).length}</dd></div>`:'<div><dt>Classement</dt><dd>Ce pays ne participe pas au prestige.</dd></div>'}</dl><p class="relation-contact-note">${f.access[c.id]?'Accès local ouvert.':'Un contact réussi peut ouvrir l’accès local.'}</p>${seen.length?`<div class="relation-sightings"><strong>Présences étrangères signalées</strong>${seen.map(a=>`<p>${flag(a.faction)} ${esc(a.name)} · Équipe ${COUNTRY[a.faction].name} · observé T${a.turn}</p>`).join('')}<small>Dernière observation connue ; mission et position actuelle non confirmées.</small></div>`:'<p class="relation-contact-note">Aucune présence étrangère signalée.</p>'}<div class="relation-actions">${button('Voir le pays','map-country','small','data-id="'+c.id+'"')}${own?button('Gouvernement','nav','small','data-id="government"'):''}</div></div></details></article>`;}
function diplomacyScreen(){const powers=COUNTRIES.filter(c=>c.power).sort((a,b)=>state.factions[b.id].score-state.factions[a.id].score);return `${heading('05 / COOPÉRATION','Diplomatie','Relations, accès et protection en un coup d’œil.')}<details class="panel"><summary>Règles de coopération des autorités</summary>${cooperationRules}</details><section class="relations-section"><h2>Puissances <small>Classées par prestige</small></h2><div class="relations-grid">${powers.map(countryRelation).join('')}</div></section><section class="relations-section"><h2>Autres pays <small>Hors classement</small></h2><div class="relations-grid">${COUNTRIES.filter(c=>!c.power).map(countryRelation).join('')}</div></section><section class="diplomacy-followup"><h2>Activité internationale</h2>${internationalActivity(state)}</section>`;}
function governmentScreen(){return `<h1 class="sr-only">Gouvernement</h1>${nationalPanel(state)}`;}
function journalScreen(){return `${heading('07 / ARCHIVES','Journal d’opération','Chaque décision laisse une trace.')}<section class="panel">${prestigeHistory(state)}</section><section class="panel journal-list">${activityRows(state,E.visibleLogs(state))}</section>`;}
return {threats:()=>threatPanel(state),world:worldScreen,agents:agentsScreen,inquiry:inquiryScreen,operations:operationsScreen,diplomacy:diplomacyScreen,government:governmentScreen,journal:journalScreen};
}

function activeMission(s,a){if(!a.task)return '';const t=a.task,locked=E.travelInProgress(a),target=COUNTRY[t.target]?.city||s.suspects.find(x=>x.id===t.target)?.name||'';return `<section class="focus-mission" aria-label="Mission de l’agent"><div class="focus-mission-heading"><span>${t.queued?'MISSION PLANIFIÉE':'MISSION EN COURS'}</span>${button(icon('close'),'cancel','mission-cancel',`data-id="${a.id}" aria-label="Annuler la mission de ${esc(a.name)}" title="${locked?'Déplacement commencé : annulation impossible':'Annuler la mission'}" ${locked||s.ended?'disabled':''}`)}</div><h3>${ACTIONS[t.type].name}</h3>${target?`<p>${esc(target)}</p>`:''}<strong>${t.chance} % de réussite · ${t.remaining} tour(s) restant(s)</strong><p>Fin prévue : T${s.turn+t.remaining-1}</p><progress aria-label="Progression de la mission" max="${t.total}" value="${t.total-t.remaining}"></progress><small>${locked?'Déplacement commencé · non annulable':'Annulation : progression perdue.'}</small></section>`;}
